// Paginate returns a page of ledger_entries with total count for offset-based pagination.
// A nil filter paginates all ledger_entries.
func (c *ledgerEntryClient) Paginate(ctx context.Context, input PaginateInput[LedgerEntryFilter], opts ...func(*CallOptions[LedgerEntryFieldOptions])) (*PaginateResult[LedgerEntry], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("paginate ledger_entries: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableLedgerEntries, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[LedgerEntryFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		ledgerEntries, err := c.GetMany(ctx, &GetLedgerEntriesInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		return &PaginateResult[LedgerEntry]{
			Items:      ledgerEntries,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    input.Limit > 0 && int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("paginate ledger_entries: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*PaginateResult[LedgerEntry]), nil
}

// Connection returns a Relay-style cursor-paginated connection of ledger_entries.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *ledgerEntryClient) Connection(ctx context.Context, input ConnectionInput[LedgerEntryFilter], opts ...func(*CallOptions[LedgerEntryFieldOptions])) (*Connection[LedgerEntry], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection ledger_entries: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableLedgerEntries, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[LedgerEntryFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeLedgerEntryCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeLedgerEntryCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		ledgerEntries, err := c.GetMany(ctx, &GetLedgerEntriesInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(ledgerEntries) > limit
		if hasMore {
			ledgerEntries = ledgerEntries[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(ledgerEntries)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[LedgerEntry], len(ledgerEntries))
		for i, row := range ledgerEntries {
			cursor, err := encodeLedgerEntryCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[LedgerEntry]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[LedgerEntry]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection ledger_entries: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*Connection[LedgerEntry]), nil
}

// encodeLedgerEntryCursor encodes cursor key values as a base64 JSON string.
func encodeLedgerEntryCursor(keys []string, l *LedgerEntry) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "workspace_id":
			out["workspace_id"] = l.WorkspaceID
		case "entry_id":
			out["entry_id"] = l.EntryID
		case "amount":
			out["amount"] = l.Amount
		case "ref":
			out["ref"] = l.Ref
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode ledger_entry cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeLedgerEntryCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeLedgerEntryCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row LedgerEntry
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "workspace_id":
			err = json.Unmarshal(raw[key], &row.WorkspaceID)
			out[key] = row.WorkspaceID
		case "entry_id":
			err = json.Unmarshal(raw[key], &row.EntryID)
			out[key] = row.EntryID
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

// StreamLedgerEntriesInput holds query parameters for streaming ledger_entries records.
