// resolveO2OJoins inspects FieldOptions and returns JOIN descriptors for each O2O relationship.
// Returns nil if no O2O relationships are requested.
func (c *templateStepClient) resolveO2OJoins(d sql.Dialect, fo *TemplateStepFieldOptions) []sql.JoinClause {
	if fo == nil {
		return nil
	}
	var joins []sql.JoinClause
	if fo.Template != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "public", Name: "templates"},
			Alias: "t2",
			On:    fmt.Sprintf("t2.%s = t.%s", d.QuoteIdentifier("owner_workspace"), d.QuoteIdentifier("workspace_id")) + fmt.Sprintf(" AND t2.%s = t.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("template_id")),
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.Template.Columns(), "id"),
		})
	}
	return joins
}

// scanTemplateStepsWithOneToOneJoins scans rows from a LEFT JOIN query into
// TemplateStep entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanTemplateStepsWithOneToOneJoins(rows database.Rows, columns []string) ([]*TemplateStep, error) {
	var result []*TemplateStep
	for rows.Next() {
		t := &TemplateStep{}
		t2 := &Template{}
		t2HasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "t.id":
				targets[idx] = &t.ID
			case "t.workspace_id":
				targets[idx] = &t.WorkspaceID
			case "t.template_id":
				targets[idx] = &t.TemplateID
			case "t.title":
				targets[idx] = &t.Title
			case "t2.id":
				targets[idx] = database.NullScan(&t2.ID)
				t2HasData = true
			case "t2.owner_workspace":
				targets[idx] = database.NullScan(&t2.OwnerWorkspace)
			case "t2.name":
				targets[idx] = database.NullScan(&t2.Name)
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan template_step with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if t2HasData && t2.ID != 0 {
			t.Template = t2
		} else {
			t.Template = nil
		}

		result = append(result, t)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate template_step rows: %w", err)
	}
	return result, nil
}

type Template struct {
	ID             int64     `db:"id" json:"id"`
	OwnerWorkspace uuid.UUID `db:"owner_workspace" json:"owner_workspace"`
	Name           string    `db:"name" json:"name"`

	// Labels - many-to-many relationship with the labels table.
	Labels []*Label `db:"-" json:"labels"`
	// Stamps - many-to-many relationship with the stamps table.
	Stamps []*Stamp `db:"-" json:"stamps"`
	// TemplateNotes - one-to-many relationship with the template_notes table.
	TemplateNotes []*TemplateNote `db:"-" json:"template_notes"`
	// TemplateSteps - one-to-many relationship with the template_steps table.
	TemplateSteps []*TemplateStep `db:"-" json:"template_steps"`
}

// TemplateClient provides type-safe operations for the templates table.
type TemplateClient interface {
	// --- Read Operations ---

	// Get returns a single template by primary key.
	Get(ctx context.Context, id int64, opts ...func(*CallOptions[TemplateFieldOptions])) (*Template, error)

	// GetMany returns templates matching the given filter, field selection, and sort criteria.
	// When FieldOptions includes O2M or M2M relationships, they are loaded via an
	// errgroup fan-out — in parallel over the pool, and serialized by the
	// transaction's connection reservation when ctx carries one.
	GetMany(ctx context.Context, input *GetTemplatesInput, opts ...func(*CallOptions[TemplateFieldOptions])) ([]*Template, error)

	// Exists returns true if a template with the given primary key exists.
	Exists(ctx context.Context, id int64, opts ...func(*CallOptions[TemplateFieldOptions])) (bool, error)

	// ExistsWhere returns true if any template matches the given filter.
	ExistsWhere(ctx context.Context, filter *TemplateFilter, opts ...func(*CallOptions[TemplateFieldOptions])) (bool, error)

	// Count returns the number of templates matching the given filter.
	Count(ctx context.Context, filter *TemplateFilter, opts ...func(*CallOptions[TemplateFieldOptions])) (int64, error)

	// --- Write Operations ---

	// Create inserts a new template and returns the created entity.
	Create(ctx context.Context, input *CreateTemplateInput, opts ...func(*CallOptions[TemplateFieldOptions])) (*Template, error)

	// CreateMany inserts multiple templates in batches and returns all created entities.
	// Sub-batches are not automatically rolled back on failure — wrap in a transaction for atomicity.
	CreateMany(ctx context.Context, inputs []*CreateTemplateInput, opts ...func(*CallOptions[TemplateFieldOptions])) ([]*Template, error)

	// Update partially updates a template by primary key and returns the updated entity.
	// Only fields where IsSet() is true are included in the SET clause.
	// Returns ErrNotFound if the primary key does not exist.
	Update(ctx context.Context, id int64, input *UpdateTemplateInput, opts ...func(*CallOptions[TemplateFieldOptions])) (*Template, error)

	// UpdateMany updates multiple templates and returns the updated entities.
	UpdateMany(ctx context.Context, items []UpdateTemplateItem, opts ...func(*CallOptions[TemplateFieldOptions])) ([]*Template, error)

	// UpdateWhere updates all templates matching the filter and returns the updated entities.
	// Idempotent — returns empty slice when no rows match.
	UpdateWhere(ctx context.Context, filter *TemplateFilter, input *UpdateTemplateInput, opts ...func(*CallOptions[TemplateFieldOptions])) ([]*Template, error)

	// Upsert inserts a template or updates it on conflict and returns the resulting entity.
	Upsert(ctx context.Context, input *CreateTemplateInput, target TemplateConflictTarget, opts ...func(*CallOptions[TemplateFieldOptions])) (*Template, error)

	// UpsertMany inserts or updates multiple templates in batches and returns all resulting entities.
	// Inputs resolving to the same conflict target are deduped, last occurrence wins.
	UpsertMany(ctx context.Context, inputs []*CreateTemplateInput, target TemplateConflictTarget, opts ...func(*CallOptions[TemplateFieldOptions])) ([]*Template, error)

	// CreateWithRelated creates a template together with rows on its nested
	// relationships, in a single transaction. Nested rows are written through
	// the target table's own client, so their hooks, events, cache
	// invalidation and tenancy behave exactly as on a direct call.
	CreateWithRelated(ctx context.Context, input *CreateTemplateWithRelatedInput, opts ...func(*CallOptions[TemplateFieldOptions])) (*Template, error)

	// UpdateWithRelated updates a template together with rows on its nested
	// relationships, in a single transaction. The nested blocks add `disconnect`
	// and `clear` to the create-side verbs, because the parent already exists
	// and there are rows to unlink.
	UpdateWithRelated(ctx context.Context, id int64, input *UpdateTemplateWithRelatedInput, opts ...func(*CallOptions[TemplateFieldOptions])) (*Template, error)

	// UpsertWithRelated inserts or updates a template together with rows on
	// its nested relationships, in a single transaction. It reuses the
	// update-side nested block verbatim — each verb means the same thing on
	// either branch, so one block is correct on both. `create` is not
	// idempotent: repeating an upsert that carries it inserts again.
	UpsertWithRelated(ctx context.Context, input *UpsertTemplateWithRelatedInput, target TemplateConflictTarget, opts ...func(*CallOptions[TemplateFieldOptions])) (*Template, error)

	// --- Hard Delete Operations ---

	// HardDelete permanently removes a template from the database.
	// Idempotent — returns nil if the primary key does not exist.
	HardDelete(ctx context.Context, id int64, opts ...func(*CallOptions[TemplateFieldOptions])) error

	// HardDeleteMany permanently removes multiple templates from the database.
	HardDeleteMany(ctx context.Context, ids []int64, opts ...func(*CallOptions[TemplateFieldOptions])) error

	// HardDeleteWhere permanently removes all templates matching the filter.
	// Idempotent — returns nil when no rows match.
	HardDeleteWhere(ctx context.Context, filter *TemplateFilter, opts ...func(*CallOptions[TemplateFieldOptions])) error

	// --- Pagination Operations ---

	// Paginate returns a page of templates with total count for offset-based pagination.
	Paginate(ctx context.Context, input PaginateInput[TemplateFilter], opts ...func(*CallOptions[TemplateFieldOptions])) (*PaginateResult[Template], error)

	// Connection returns a Relay-style cursor-paginated connection of templates.
	// Sort order is determined by cursor_keys — custom sorts are not supported.
	// Use Paginate for custom sort orders.
	Connection(ctx context.Context, input ConnectionInput[TemplateFilter], opts ...func(*CallOptions[TemplateFieldOptions])) (*Connection[Template], error)

	// Stream returns an iterator over templates matching the filter and sort criteria.
	// Rows are yielded as the driver returns them; cache is bypassed.
	// Stream cannot load relationships.
	//
	// Stream refuses an active transaction unless CallOptions.AllowInTransaction
	// is set, and the opt-in commits the caller to issuing nothing else on that
	// txCtx: the one rule that remains the caller's — drain or close a result set
	// before issuing the next statement on that txCtx — applied to a loop whose
	// body is caller code.
	Stream(ctx context.Context, input *StreamTemplatesInput, opts ...func(*CallOptions[StreamTemplateFieldOptions])) iter.Seq2[*Template, error]
}

